from pathlib import Path
import json,hashlib
base=Path(__file__).resolve().parents[2]; src=base/'source'; out=base/'audit'
rows=[]
def add(file,claim,ranges,missing,scope='Static component behavior; no runtime/UI acceptance certification'):
 p='packages/ui/src/'+file; lines=(src/p).read_text().splitlines(); evidence=[]
 for a,b in ranges:
  assert 1<=a<=b<=len(lines),(p,a,b,len(lines))
  evidence.append(dict(file=p,startLine=a,endLine=b,excerpt='\n'.join(lines[a-1:b])))
 rows.append(dict(file=p,claim=claim,scope=scope,auditDepth='SEMANTIC_SOURCE_REVIEW',evidence=evidence,missingProof=missing,runtimeStatus='NOT_EXECUTED',sourceSha256=hashlib.sha256((src/p).read_bytes()).hexdigest()))
add('catalogs/CatalogPicker.tsx','Filters active catalog entries while preserving a selected inactive entry; searches code/name/subtitle, supports arrow/Enter/Escape search navigation and listbox selection; clearing is wired onMouseDown rather than onClick.',[(70,116),(175,208),(270,290),(335,350)],'Browser keyboard activation of clear, focus restoration, popover clipping and screen-reader combobox semantics remain untested.')
add('catalogs/ambient/AmbientCategoryTree.tsx','Recursive category filtering toggles the selected category; management rows invoke edit/delete callbacks, with deletion rendered only when canDelete permits. This component does not persist or enforce hierarchy validity.',[(20,77),(84,150)],'Caller permissions, cyclic category input handling, keyboard/screen-reader selected-state feedback and server persistence remain unverified.')
add('catalogs/hardware/HardwareMachiningSection.tsx','Edits hardware-owned machining parts and operations immutably; type changes retain ID/offset/face but reset kind-specific defaults. Prevents deleting the last operation, converts numeric inputs with Number, and delegates complete profile validation/persistence to the enclosing form.',[(80,139),(243,300),(382,430)],'Domain validation and save rollback must be proved at parent boundary; no host placement, machining output or physical compatibility claim.')
add('catalogs/materials/MaterialExpandedDetail.tsx','Read-only material detail resolves image and displays dimensions/grain/edge/cost/waste/status. Board price and cost per area are rendered by this child without a hideCosts gate; this alone does not establish unauthorized exposure.',[(24,101)],'Caller visibility and API cost redaction, broken-image UX and responsive detail layout remain unverified.')
